/* KON Dash — standalone, interactive redesign prototype. All edits are browser-local. */
(() => {
'use strict';
const $=id=>document.getElementById(id);
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safe=(s,n=150)=>escape(String(s??'').slice(0,n));
let detailTab='overview';
// Session-only chat attachments: no uploaded file bytes are stored in localStorage.
let chatAttachments=[],agentAttachments=[];
let db={},org='org-harbor',page='home',filter='All',discoverScope='project',query='',picked='',sourcePicked='',wizardStep=0,createKind='agent',editor=null,selectedTab='all',simChat=[],status='',dirty=false,selectedChat='',previewId='',demoPrompt='',demoReply='',demoRun=false,appResult=null;
const typeMap={agents:'Agent',apps:'App',knowledgeBases:'Knowledge Base',projects:'Project',scheduledTasks:'Automation',agentSkills:'Skill',mcpServers:'MCP Server'};
const icons={home:'⌂',chat:'⊕',discover:'✧',create:'✦',connections:'⇄',share:'♧',projects:'▣',knowledge:'▤',automations:'◷',extensions:'⚒',memory:'◉',settings:'⚙'};
const cats=['agents','apps','knowledgeBases','projects','scheduledTasks','agentSkills','mcpServers'];
const mainLinks=[['chat','Chat'],['discover','Discover'],['create','Create'],['projects','Projects'],['manage','Manage']];
const storeKey='kon-dash-redesign-v1';
const supportedPreview=/\.(txt|md|csv|json|log)$/i;
const fileLimit=5*1024*1024;
const attachmentsSummary=arr=>arr.map(f=>f.name).join(', ');
function attachmentPills(arr,kind){return arr.length?`<div class="attached-list">${arr.map((f,i)=>`<div class="attached-chip"><span>▤ <b>${safe(f.name,65)}</b> <small>${f.text!==null?'Text preview available':'File attached · metadata only'}</small></span><button aria-label="Remove attachment" title="Remove attachment" data-remove-file="${kind}:${i}">×</button></div>`).join('')}</div>`:''}
function attachmentTrace(arr){return arr.length?arr.map(f=>`<div class="attachment-source"><b>▤ ${safe(f.name,75)}</b><small>${f.text===null?'Attached only · contents not read':`Local text preview · ${f.text.length.toLocaleString()} characters`}</small>${f.text!==null?`<details><summary>View document excerpt</summary><pre>${safe(f.text.slice(0,1500),1500)}</pre></details>`:''}</div>`).join(''):'<p class="sub">No files attached to this conversation.</p>'}
async function receiveFiles(fileList,kind){const target=kind==='agent'?agentAttachments:chatAttachments;for(const f of [...fileList]){if(target.length>=5){status='You can attach up to five files in one conversation.';break}if(f.size>fileLimit){status='File too large: '+f.name+'. Maximum is 5 MB per file.';continue}const preview=supportedPreview.test(f.name);let textContent=null;try{if(preview)textContent=(await f.text()).slice(0,12000)}catch{status='Unable to preview '+f.name+'; its name can still be shown.'}target.push({name:f.name.slice(0,120),size:f.size,text:textContent})}render();if(status)showNotice()}
function agentAppPicker(a){const current=new Set(a.appIds||[]),options=all('apps').filter(x=>!current.has(x.id));return `<div class="connection-add"><h3>Reuse an existing App</h3><p class="sub">Attach an organization App to this agent. The same App can be reused by other agents.</p><div class="row"><select id="existingAppSelect" aria-label="Choose an App">${options.map(x=>`<option value="${escape(x.id)}">${safe(x.name,85)}</option>`).join('')}</select><button class="btn" data-action="linkExistingApp" ${options.length?'':'disabled'}>＋ Add App to agent</button></div></div>`}
function demoSources(a,attachments){const kbs=(a.knowledgeBaseIds||[]).map(id=>record('knowledgeBases',id)).filter(Boolean),apps=(a.appIds||[]).map(id=>record('apps',id)).filter(Boolean);return `<div class="trace-panel"><div class="section-top"><h3>Sources & tools</h3><span class="pill">Configuration trace</span></div><p class="sub">These are the resources available to the agent, <b>not</b> documents retrieved to produce this demo reply.</p><h4>Knowledge bases</h4>${kbs.length?kbs.map(x=>`<div class="info-line"><span>▤ ${safe(x.name,75)}</span><small class="muted">Configured</small></div>`).join(''):'<p class="sub">None linked</p>'}<h4>Apps</h4>${apps.length?apps.map(x=>`<div class="info-line"><b>${safe(x.name,75)}</b><button class="btn slim" data-open-app="${escape(x.id)}">Open App →</button></div>`).join(''):'<p class="sub">None linked</p>'}<h4>Chat files</h4>${attachmentTrace(attachments)}<div class="notice">No model, document search, citation generation or external tool was executed.</div></div>`}

let local={};
function readLocal(){try{local=JSON.parse(localStorage.getItem(storeKey)||'{}')}catch{local={}};if(!local||typeof local!=='object')local={}}
function saveLocal(){try{localStorage.setItem(storeKey,JSON.stringify(local));return true}catch{status='Browser storage is unavailable; changes will last only until reload.';return false}}
const baseArr=type=>(db.kondash?.[type]||[]).filter(x=>x.organizationId===org);
const extraArr=type=>(local[org]?.[type]||[]);
const all=type=>[...baseArr(type),...extraArr(type)].map(x=>({...x,...activeState(x.id)}));
function record(type,id){return all(type).find(x=>x.id===id)}
function orgObj(){return db.organizations.find(x=>x.id===org)||db.organizations[0]}
const orgName=()=>orgObj()?.name||'';
function activeState(id){return local[org]?.settings?.[id]||{}}
function setState(id,value){local[org]??={};local[org].settings??={};local[org].settings[id]={...activeState(id),...value};saveLocal()}
function addRecord(type,obj){local[org]??={};local[org][type]??=[];local[org][type].unshift(obj);saveLocal()}
function updateRecord(type,id,obj){const list=extraArr(type);const i=list.findIndex(x=>x.id===id);if(i>=0){list[i]={...list[i],...obj};saveLocal()}else setState(id,obj)}
function findAny(id){for(const type of cats){const rec=record(type,id);if(rec)return{...rec,type}}return null}
function itemName(type,id){return record(type,id)?.name||'Unknown resource'}
// Project membership is separate from organization-wide visibility.
// Original fictional project records have knowledgeBaseIds but no explicit agentIds.
// Associations added by users are therefore saved in browser-local settings only.
function projectAgentIds(projectId){if(!projectId)return [];const p=record('projects',projectId);if(!p)return [];return [...new Set(activeState(projectId).linkedAgentIds??(p.agentIds||[]))].filter(id=>!!record('agents',id))}
function projectAgents(projectId){return projectAgentIds(projectId).map(id=>record('agents',id)).filter(Boolean)}
function setProjectAgents(projectId,ids){setState(projectId,{linkedAgentIds:[...new Set(ids)]})}
function selectedProject(){return record('projects',local.project||'')}
function selectedProjectAgentOptions(){const p=selectedProject();if(!p)return [{value:'',name:'Choose an agent'},...all('agents').map(a=>({value:a.id,name:a.name}))];return [{value:'',name:'No agent selected'},...projectAgents(p.id).map(a=>({value:a.id,name:a.name}))]}
function projectIndicator(){const p=selectedProject();if(!p)return '<span class="context-note">No project · organization agents are available</span>';return `<span class="context-note">${safe(p.name,45)} · ${projectAgentIds(p.id).length} linked agent(s) <button class="context-link" data-action="projectDetails">Manage project agents →</button></span>`}
function projectBadgeForAgent(x){if(x.type!=='agents')return '';const names=all('projects').filter(p=>projectAgentIds(p.id).includes(x.id)).map(p=>p.name);return `<div class="project-meta"><b>Project membership</b><span>${names.length?names.map(n=>safe(n,54)).join(' · '):'Available to organization · not linked to a project'}</span></div>`}

function visibility(o){const st=activeState(o.id);return st.visibility||(o.public===true||o.isPublic===true?'organization':o.public===false||o.isPublic===false?'private':'team')}
function owned(o){return !!extraArr(o.type||'agents').find(x=>x.id===o.id)}
function icon(type){return ({agents:'✧',apps:'▦',knowledgeBases:'▤',projects:'▣',scheduledTasks:'◷',agentSkills:'⚒',mcpServers:'⇄'})[type]||'◇'}
function selector(opts,val,attrs=''){return `<select ${attrs}>${opts.map(x=>`<option value="${escape(x.value)}" ${x.value===val?'selected':''}>${escape(x.name)}</option>`).join('')}</select>`}
function pageHeading(title,subtitle,extra='',eyebrow='KON DASH / REDESIGN'){return `<header class="head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="sub">${subtitle}</p></div>${extra}</header>`}
function button(label,action,style=''){return `<button class="btn ${style}" data-action="${action}">${label}</button>`}
function shell(){
const chats=baseArr('chats').slice().sort((a,b)=>String(b.modified||'').localeCompare(String(a.modified||''))).slice(0,4);
return `<div class="shell"><aside class="side"><div class="brand-row"><button class="logo" data-page="home" aria-label="KON Dash home">KON<b>DASH</b></button><span class="collapse-mark">‹</span></div><div class="nav-list"><div class="nav-section">WORKSPACE</div>${mainLinks.map(([p,n])=>`<button class="nav-item ${p===page||p==='discover'&&['toolDetails','agentTry','appPreview','automationPreview'].includes(page)?'active':''}" data-page="${p}"><span class="sym">${icons[p]||'⚙'}</span><span class="caption">${n}</span></button>`).join('')}<div class="side-divider"></div><div class="nav-section">RECENT CHATS</div><div class="side-chats">${chats.map(c=>`<button class="side-chat" data-chat="${escape(c.id)}"><span>${safe(c.title,30)}</span></button>`).join('')||'<small class="muted">No recent conversations</small>'}</div></div><div class="side-bottom"><span class="side-version">KON Dash · Workspace</span></div></aside><div class="workspace"><div class="canvas"><div class="topbar"><label class="top-control top-model"><span>Model</span>${selector([{value:'fast',name:'Fast assistant'},{value:'general',name:'General assistant'},{value:'reasoning',name:'Reasoning assistant'},{value:'vision',name:'Vision assistant'}],local.model||'general','id="topModel"')}</label><label class="top-control top-project"><span>Project</span>${selector([{value:'',name:'No project'},...all('projects').map(x=>({value:x.id,name:x.name}))],local.project||'','id="topProject"')}</label></div><div class="org-strip">${projectIndicator()}<label>Workspace ${selector(db.organizations.map(o=>({value:o.id,name:o.name})),org,'id="orgSelect"')}</label></div><main class="main" id="main">${renderPage()}</main></div></div></div>`}

function render(){const f=document.activeElement;const cursor=(f?.id==='searchBox'||f?.id==='chatPrompt')?{id:f.id,start:f.selectionStart,end:f.selectionEnd}:null;const scroll=window.scrollY;$('app').innerHTML=shell();if(cursor&&$(cursor.id)){const el=$(cursor.id);el.focus();try{el.setSelectionRange(cursor.start,cursor.end)}catch{}}if(scroll>0)window.scrollTo(0,scroll)}
function open(p){page=p;status='';window.scrollTo(0,0);render()}
function renderPage(){switch(page){case'home':return home();case'discover':return discover();case'toolDetails':return toolDetails();case'agentTry':return agentTry();case'appPreview':return appPreview();case'automationPreview':return automationPreview();case'create':return builder();case'connections':return connections();case'share':return share();case'projects':return listing('projects');case'projectDetails':return projectDetails();case'knowledge':return listing('knowledgeBases');case'automations':return listing('scheduledTasks');case'chat':return chat();case'extensions':return extensionPage();case'memory':return memoryPage();case'settings':return settingsPage();case'manage':return managePage();default:return home()}}
function home(){
const types=[['discover','✧','Explore tools','Find and try agents, apps and automations'],['create','＋','Create a tool','Build an agent, app or automation'],['projects','▣','Projects','Organize tools and knowledge']];
return `<div class="home-hero"><div><div class="eyebrow">KON DASH · YOUR WORKSPACE</div><h1>What would you like to do?</h1><p class="sub">Chat, find an existing tool, or build one in a few steps.</p></div></div>
<div class="home-composer">${composer()}</div><div class="action-grid home-cards">${types.map(([dest,i,t,d])=>`<button class="action" data-page="${dest}"><span class="ico">${i}</span><strong>${t}</strong><span>${d}</span><span class="action-arrow">→</span></button>`).join('')}</div>
<div class="section-top"><h2>Recent in your workspace</h2>${button('Explore all tools →','discover')}</div>
<div class="tri-cols">${[['projects','Projects'],['agents','Agents'],['knowledgeBases','Knowledge Bases']].map(([type,title])=>`<section class="card recent-panel"><div class="section-top"><h3>${title}</h3><span class="pill">${all(type).length}</span></div>${all(type).slice(0,3).map(x=>`<div class="mini-row" data-item="${escape(x.id)}"><div><b>${safe(x.name,65)}</b><span>${safe(x.description,85)}</span></div><span>↗</span></div>`).join('')||'<div class="empty">No resources yet. Create your first tool.</div>'}</section>`).join('')}</div>`}

function composer(){return `<div class="composer"><textarea id="chatPrompt" placeholder="Ask a question or describe what you want to do…">${escape(local.draftPrompt||'')}</textarea>${attachmentPills(chatAttachments,'chat')}<div class="toolbar"><div class="row"><label class="file-attach">＋ Attach files<input type="file" id="chatAttachInput" multiple accept=".txt,.md,.csv,.json,.log,.pdf,.docx,.xlsx,.png,.jpg,.jpeg"></label><span class="tag">Chat-only documents</span><span class="tag">AI response preview</span></div>${button('→ Send','sendChat','primary')}</div><p class="attach-hint">Documents stay in this browser session. TXT, MD, CSV and JSON have a local text preview; other files show name only.</p></div>`}
function gather(){return cats.flatMap(type=>all(type).map(x=>({...x,type}))).filter(x=>x.type!=='agentSkills'&&x.type!=='mcpServers')}
function discover(){
 const project=selectedProject();
 let items=gather();
 const options=['All','Agents','Apps','Automations','Knowledge bases','Projects'];
 const ftypes={'Agents':'agents','Apps':'apps','Knowledge bases':'knowledgeBases','Projects':'projects','Automations':'scheduledTasks'};
 const projectScope=!!project&&discoverScope==='project';
 if(projectScope){
   const agentIds=new Set(projectAgentIds(project.id));
   const kbIds=new Set(project.knowledgeBaseIds||[]);
   items=items.filter(x=>x.type==='projects'?x.id===project.id:x.type==='agents'?agentIds.has(x.id):x.type==='knowledgeBases'?kbIds.has(x.id):false);
 }
 items=items.filter(x=>(filter==='All'||(ftypes[filter]?x.type===ftypes[filter]:filter==='Shared'?visibility(x)!=='private':visibility(x)==='private'))&&(!query||[x.name,x.description,visibility(x)].join(' ').toLowerCase().includes(query.toLowerCase())));
 if(!items.some(x=>x.id===picked))picked=items[0]?.id||'';
 const sel=items.find(x=>x.id===picked);
 const scopedControls=project?`<div class="library-scope"><div><b>Browsing: ${projectScope?'This project':'Organization library'}</b><p class="sub">${projectScope?`Only agents explicitly added to ${safe(project.name,60)}, its project knowledge bases, and the project itself. Other organization agents are not automatically linked.`:'All available organization tools. Agents shown here are reusable; they are not necessarily linked to the selected project.'}</p></div><div class="scope-actions"><button class="chip ${projectScope?'selected':''}" data-discover-scope="project">This project</button><button class="chip ${!projectScope?'selected':''}" data-discover-scope="organization">Organization library</button>${projectScope?button('Manage project agents →','projectDetails'):''}</div></div>`:`<div class="library-scope"><div><b>Browsing: Organization library</b><p class="sub">No project selected. These are all available organization resources; select a project above to see its linked agents.</p></div></div>`;
 const emptyText=projectScope?'No tools match this project. Add an existing agent in Manage project agents, or switch to Organization library.':'No matching tools. Try another search or create a new tool.';
 return pageHeading('Discover','Find and try an existing tool, or create your own.',button('＋ Create new tool','create','primary'))+scopedControls+`<input class="search" id="searchBox" placeholder="Search tools by name, purpose or description…" value="${escape(query)}"><div class="filters">${options.map(x=>`<button class="chip ${x===filter?'selected':''}" data-filter="${escape(x)}">${x}</button>`).join('')}</div><div class="library-layout"><div class="tool-grid">${items.map(x=>toolCard(x)).join('')||`<div class="empty">${emptyText}</div>`}</div><aside class="card inspector">${sel?inspector(sel):'<div class="empty">Select a tool to see its details.</div>'}</aside></div>`;
}
function toolCard(x){return `<button class="tool-card ${picked===x.id?'selected':''}" data-select="${escape(x.id)}"><div class="row between"><span class="iconbox">${icon(x.type)}</span><span class="pill">${typeMap[x.type]}</span></div><h3>${safe(x.name,80)}</h3><p>${safe(x.description||x.prompt||'Reusable workspace resource.',165)}</p><div class="metadata">${visibility(x)==='private'?'🔒 Private':visibility(x)==='team'?'♧ Team':'◎ Organization'} · ${x.origin==='preinstalledByKonDash'?'Built-in':owned(x)?'Created in demo':'Organization tool'}</div>${projectBadgeForAgent(x)}</button>`}
function connectionsFor(x){const links=[];for(const [key,type] of [['knowledgeBaseIds','knowledgeBases'],['skillIds','agentSkills'],['pluginIds','plugins'],['mcpServerIds','mcpServers'],['appIds','apps']]){for(const id of x[key]||[]){let name=type==='plugins'?baseArr('plugins').find(v=>v.id===id)?.name:itemName(type,id);if(name)links.push({id,type,name})}}if(x.agentId)links.push({id:x.agentId,type:'agents',name:itemName('agents',x.agentId)});return links}
function inspector(x){const links=connectionsFor(x);return `<div class="section-top"><h2>Selected tool</h2><span class="pill">${typeMap[x.type]}</span></div><div class="heading"><span class="iconbox">${icon(x.type)}</span><div><h3>${safe(x.name,90)}</h3><p class="sub">${safe(x.description||x.prompt||'',250)}</p></div></div><hr><h3>What is it for?</h3><p class="sub">${safe(x.usageDescription||x.description||x.prompt||'Reusable resource in the KON Dash workspace.',320)}</p><hr><h3>Connected resources</h3><div class="k-list">${links.length?links.map(z=>`<span class="tag">${safe(z.name,55)}</span>`).join(''):'<span class="muted small">No linked resources in this example.</span>'}</div><hr><h3>Who can use it?</h3><div class="k-list"><span class="tag">${visibility(x)==='private'?'Private':visibility(x)==='team'?'Team':'Organization'}</span></div><div style="margin-top:22px" class="row">${x.type==='agents'?button('▶ Try agent','tryAgent','primary'):x.type==='apps'?button('▦ Preview app','previewApp','primary'):x.type==='scheduledTasks'?button('▶ Preview run','previewAutomation','primary'):button('View connections','connections','primary')}${button('Manage access','share')}</div>`}
function toolDetails(){
 const x=findAny(picked);if(!x)return pageHeading('Tool details','Select a resource from Discover tools.')+button('← Back to Discover','discover');
 sourcePicked=x.id;const links=connectionsFor(x), vis=visibility(x),st=activeState(x.id);
 const primary=x.type==='agents'?button('▶ Try agent','tryAgent','primary'):x.type==='apps'?button('▦ Preview app','previewApp','primary'):x.type==='scheduledTasks'?button('▶ Preview run','previewAutomation','primary'):button('Explore connections','connections','primary');
 const tabs=[['overview','Overview'],['connections','Knowledge & connections'],['access','Access & sharing']];
 const tabbar=`<div class="detail-tabs" role="tablist">${tabs.map(([id,n])=>`<button class="detail-tab ${detailTab===id?'active':''}" data-detail-tab="${id}" role="tab" aria-selected="${detailTab===id}">${n}</button>`).join('')}</div>`;
 let content='';
 if(detailTab==='overview')content=`<div class="detail-intro"><h3>What does this tool do?</h3><p class="detail-copy">${safe(x.description||x.prompt||'Reusable tool in the workspace.',750)}</p></div>${x.type==='scheduledTasks'?`<div class="detail-summary"><b>Schedule</b><span>${safe(x.schedulePreset||'Daily',35)} · ${safe(x.scheduleTime||'09:00',8)} · ${safe(x.timeZoneId||'UTC',40)}</span><small>Demo only · no background execution</small></div>`:''}${x.type==='apps'?`<div class="detail-summary"><b>App layout</b><span>${safe(x.appFormat||'Interactive',45)}</span><small>Preview includes sample inputs and outputs</small></div>`:''}<div class="detail-summary"><b>Visibility</b><span>${vis==='organization'?'Organization':vis==='team'?'Team':'Private'}</span></div><div class="detail-cta">${primary}</div>`;
 else if(detailTab==='connections')content=`<h3>Connected resources</h3><p class="sub">These are the document collections, tools and components configured for this resource.</p>${links.length?`<div class="detail-link-list">${links.map(z=>`<div class="info-line"><span><b>${safe(z.name,85)}</b></span><span class="pill">${safe(typeMap[z.type]||'Plugin',30)}</span></div>`).join('')}</div>`:'<div class="empty">No connections yet. You can link a knowledge base below.</div>'}<div class="row detail-actions">${button('＋ Link knowledge base','addConnection')}${button('Open visual connection map →','connections')}${x.type==='agents'?agentAppPicker(x):''}</div><p class="footnote">These are data relationships, not live AI retrieval or execution traces.</p>`;
 else content=`<h3>Who can use this tool?</h3><p class="sub">Choose the visibility and authorized teams. Changes are browser-local demos.</p><div class="share-choice" style="margin:20px 0">${[['private','Private','Only you'],['team','Team','Selected groups'],['organization','Organization','Everyone in this organization']].map(([k,n,d])=>`<label><input name="shareVis" type="radio" value="${k}" ${vis===k?'checked':''}> ${n}<small>${d}</small></label>`).join('')}</div><h3 style="margin:12px 0">Team access</h3><div class="access-teams">${all('groups').map(g=>`<label class="info-line"><span>${safe(g.name,72)}</span><input type="checkbox" class="toggle" data-shareteam="${escape(g.id)}" ${(st.teamIds||[]).includes(g.id)?'checked':''}></label>`).join('')||'<p class="sub">No groups listed.</p>'}</div><div class="row detail-actions">${button('✓ Save access settings','saveSharing','primary')}</div><p class="footnote">Access controls are illustrative and not enforced by a backend.</p>`;
 return `<div class="detail-top"><button class="btn" data-action="discover">← Back to Discover</button><span class="pill">${escape(typeMap[x.type]||'Tool')}</span></div><div class="tool-focus"><div class="tool-focus-head"><span class="iconbox">${icon(x.type)}</span><div><h1>${safe(x.name,95)}</h1><p class="sub">${safe(x.description||'Reusable organization tool',190)}</p><span class="muted tiny">${safe(orgName(),70)} · ${owned(x)?'Created in this browser':'Sample data'}</span></div></div><section class="card tool-focus-card">${tabbar}<div class="detail-content">${content}</div></section></div>`;
}

function previewRecord(type){return record(type,previewId)||null}
function previewBanner(){return `<div class="demo-flag"><span class="pill">DEMO PREVIEW · NO LIVE SERVICE</span><span>Everything shown here is a local, fictional demonstration. No actual model, shipment system or scheduler is connected.</span></div>`}
function agentTry(){
 const a=previewRecord('agents');if(!a)return pageHeading('Try agent','Choose an agent from Discover tools.')+button('Back to library','discover');
 return `<div class="detail-top"><button class="btn" data-action="backTool">← Back to agent details</button><span class="pill">${safe(orgName())}</span></div>`+pageHeading('Try '+safe(a.name,100),'Ask a sample question, attach a file and inspect configured sources and tools.',`<span class="pill">Interactive demonstration</span>`)+previewBanner()+`<div class="two-col"><section class="card"><div class="demo-thread"><div class="demo-message demo-assistant"><b>${safe(a.name,85)}</b><p>Ask a sample question or attach a document. The reply is a predefined simulation.</p></div>${demoPrompt?`<div class="demo-message demo-user"><b>Your question</b><p>${safe(demoPrompt,600)}</p></div><div class="demo-message demo-assistant"><b>Simulated reply · not generated by AI</b><p>${safe(demoReply,1300)}</p></div>`:''}</div><div class="field" style="margin-top:19px"><label for="demoQuestion">Ask a question</label><textarea id="demoQuestion" placeholder="How can I check the status of a customer shipment?">${escape(local.demoQuestionDraft||'')}</textarea></div>${attachmentPills(agentAttachments,'agent')}<div class="row" style="margin-top:12px"><label class="file-attach">＋ Attach file<input type="file" id="agentAttachInput" multiple accept=".txt,.md,.csv,.json,.log,.pdf,.docx,.xlsx,.png,.jpg,.jpeg"></label>${button('Send sample question →','sendDemoQuestion','primary')}${button('Use example question','fillDemoQuestion')}</div><p class="attach-hint">Attached files are kept only in this session. Plain-text excerpts can be viewed on the right, but do not influence the simulated reply.</p></section><aside class="card">${demoSources(a,agentAttachments)}<hr><h3>Agent instructions</h3><p class="sub">${safe(a.systemPrompt||a.description,450)}</p>${button('View connection map','connections')}</aside></div>`
}

function mockAgentReply(agent,question){const q=question.toLowerCase();const kbs=(agent.knowledgeBaseIds||[]).map(id=>record('knowledgeBases',id)?.name).filter(Boolean);let body;if(/ship|deliver|tracking|order|encomenda|entrega|transport/.test(q))body='To check a shipment, open the shipment tracking system and search using the customer reference or tracking number. Confirm the current status and expected delivery window before replying to the customer. If the status is unclear, contact the operations team.';else if(/custom|alfand|border|import|export/.test(q))body='For customs questions, check the current customs procedure, required shipment documents and the destination country. Confirm the applicable rules with the customs team before advising the customer.';else body='I would first review the relevant organization knowledge, check the details supplied in the request, and provide a concise answer with any follow-up steps. When information is missing, I would ask for clarification rather than invent facts.';return `${body}\n\nConfigured knowledge: ${kbs.length?kbs.join('; '):'none selected'}. This is a predefined demo reply, not a live answer or document retrieval.`}
function isShippingCalculator(a){return a.appFormat==='calculator'||/ship|freight|transport|cost|price/i.test(a.name+' '+a.description)}
function appPreview(){const a=previewRecord('apps');if(!a)return pageHeading('App preview','Choose an app from Discover tools.')+button('Back to library','discover');const calc=isShippingCalculator(a);
 return `<div class="detail-top"><button class="btn" data-action="backTool">← Back to app details</button></div>`+pageHeading('Preview · '+safe(a.name,100),'Interact with a sample version of the application you configured.')+previewBanner()+`<div class="two-col"><section class="card"><div class="section-top"><h2>${calc?'Shipping cost calculator':'App form preview'}</h2><span class="pill">${calc?'Demo calculator':'Demo form'}</span></div>${calc?`<div class="fields">${field('Distance (km)','appDistance',appResult?.distance??120,'number')}${field('Shipment weight (kg)','appWeight',appResult?.weight??20,'number')}${selectField('Transport type','appTransport',[{value:'road',name:'Road'},{value:'express',name:'Express road'},{value:'air',name:'Air'}],appResult?.transport??'road')}</div><p class="sub">Illustrative formula: fixed handling fee $10 + distance × transport rate + weight × $0.12/kg. Rates: Road $0.45/km, Express $0.75/km, Air $1.80/km. Not actual Konverto prices.</p>`:`<div class="fields">${field('Customer / request','appCustomer',appResult?.customer??'Example customer')}${field('Request details','appRequest',appResult?.request??'Please prepare a shipment summary.','textarea',true)}</div>`}<div class="row" style="margin-top:20px">${button(calc?'Calculate demo price':'Generate preview','calculateDemoApp','primary')}${button('Reset','resetDemoApp')}</div>${appResult?.calculated?`<div class="demo-total"><small>${calc?'Estimated demo shipping cost':'Example output · simulation'}</small><h2>${calc?'$'+appResult.total.toFixed(2):'Request summary prepared'}</h2><p>${calc?`${appResult.distance} km · ${appResult.weight} kg · ${appResult.transport}`:'Your request is ready for review. No real records were processed.'}</p></div>`:''}</section><aside class="card"><h2>App configuration</h2><div class="info-line"><span>Layout</span><b>${safe(a.appFormat||'Form')}</b></div><div class="info-line"><span>Input fields specified</span><b>${safe(a.inputsDescription||'Not specified',125)}</b></div><div class="info-line"><span>Expected output</span><b>${safe(a.outputDescription||'Not specified',125)}</b></div><hr><p class="sub">This interactive preview shows what an app could look like. The shipping estimate is computed locally using explicitly fictional rates, independent of the app's description.</p></aside></div>`}
function dateInTZ(date,tz){return new Intl.DateTimeFormat('en-CA',{timeZone:tz,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23',weekday:'short'}).formatToParts(date).reduce((o,p)=>(o[p.type]=p.value,o),{})}
function nextRun(a){let tz=a.timeZoneId||'UTC',preset=a.schedulePreset||'daily',time=a.scheduleTime||'09:00';try{new Intl.DateTimeFormat('en',{timeZone:tz}).format()}catch{tz='UTC'};const [h,m]=time.split(':').map(Number);if(!Number.isInteger(h)||!Number.isInteger(m))return 'Not configured';const now=new Date();for(let i=1;i<=32*24*60;i++){const t=new Date(Math.ceil(now.getTime()/60000)*60000+i*60000);const p=dateInTZ(t,tz);const day=new Date(`${p.year}-${p.month}-${p.day}T12:00:00Z`).getUTCDay();const validDay=preset==='weekdays'?day>=1&&day<=5:preset==='weekly'?day===1:preset==='monthly'?Number(p.day)===1:true;if(validDay&&Number(p.hour)===h&&Number(p.minute)===m)return `${p.year}-${p.month}-${p.day} ${p.hour}:${p.minute} (${tz})`}return 'Not calculated'}
function automationPreview(){const a=previewRecord('scheduledTasks');if(!a)return pageHeading('Automation preview','Choose an automation from Scheduled tasks.')+button('Back to list','automations');const agent=a.agentId?record('agents',a.agentId):null;
 return `<div class="detail-top"><button class="btn" data-action="backTool">← Back to automation details</button></div>`+pageHeading('Preview run · '+safe(a.name,100),'Inspect the schedule and simulate a sample execution without scheduling a real task.')+previewBanner()+`<div class="two-col"><section class="card"><h2>Automation overview</h2><div class="info-line"><span>Repeat</span><b>${safe(a.schedulePreset||a.cronExpression||'Not configured')}</b></div><div class="info-line"><span>Local time</span><b>${safe(a.scheduleTime||'Not configured')}</b></div><div class="info-line"><span>Time zone</span><b>${safe(a.timeZoneId||'UTC')}</b></div><div class="info-line"><span>Agent</span><b>${agent?safe(agent.name,100):'No agent linked'}</b></div><div class="info-line"><span>Execution status</span><b>Demo / Not connected</b></div><div class="info-line"><span>Next scheduled occurrence (hypothetical)</span><b>${escape(nextRun(a))}</b></div><p class="sub" style="margin:16px 0">The next occurrence is calculated from the configured schedule, but this prototype will not run it automatically.</p>${button('▶ Preview run','previewDemoRun','primary')}${demoRun?`<div class="demo-total"><small>Example output · simulated execution</small><h2>Daily shipment summary</h2><p>• 24 shipments in transit<br>• 3 shipments flagged for follow-up<br>• 2 delivery exceptions require review</p><p class="tiny muted">Illustrative figures only. No system was queried, no actual messages were sent, and no task was executed.</p></div>`:''}</section><aside class="card"><h2>Task instruction</h2><p class="sub">${safe(a.prompt||a.description,700)}</p><hr><h3>Linked agent</h3><p class="sub">${agent?safe(agent.name,100):'No agent linked'}</p><hr><div class="notice">An automation would need a real backend scheduler and authorization before running. Here, Preview run demonstrates the intended result only.</div></aside></div>`}
function defaultDraft(){return {name:'',description:'',model:'general',role:'Helpful assistant',knowledgeBaseIds:[],skillIds:[],pluginIds:[],mcpServerIds:[],appIds:[],visibility:'private',teamIds:[],enabled:false,prompt:'',cronExpression:'0 9 * * *',schedulePreset:'daily',scheduleTime:'09:00',timeZoneId:'Europe/Rome',agentId:'',appFormat:'form',appInputs:'Customer question',appOutput:'A concise answer',inputs:[]}}
let draft=defaultDraft();
function startCreate(kind='agent'){createKind=kind;wizardStep=0;draft=defaultDraft();page='create';render()}
function field(label,id,value,kind='text',wide=false,help=''){return `<label class="field ${wide?'wide':''}">${label}${help?`<small>${help}</small>`:''}${kind==='textarea'?`<textarea id="${id}">${escape(value)}</textarea>`:`<input id="${id}" type="${kind}" value="${escape(value)}" ${kind==='text'?'maxlength="180"':''}>`}</label>`}
const stepsByKind={agent:['Purpose','Knowledge','Tools','Permissions','Review'],app:['App design','Data & layout','Access','Review'],automation:['Task','Schedule','Execution','Review']};
const currentSteps=()=>stepsByKind[createKind];
function modelOpts(){return db.models.filter(x=>x.id!=='image').map(x=>({value:x.id,name:x.name}))}
function selectField(label,id,opts,val,hint=''){return `<label class="field">${label}${hint?`<small>${escape(hint)}</small>`:''}${selector(opts,val,`id="${id}"`)}</label>`}
function builder(){
 const steps=currentSteps();const title={agent:'Create an agent',app:'Create an app',automation:'Create an automation'}[createKind];
 const summary=createKind==='agent'?`<div class="info-line"><span>Model</span><b>${safe(db.models.find(x=>x.id===draft.model)?.name||'Default')}</b></div><div class="info-line"><span>Knowledge</span><b>${draft.knowledgeBaseIds.length} selected</b></div>`:createKind==='app'?`<div class="info-line"><span>Layout</span><b>${escape(draft.appFormat)}</b></div><div class="info-line"><span>Inputs</span><b>${safe(draft.appInputs||'Not defined',60)}</b></div>`:`<div class="info-line"><span>Frequency</span><b>${escape(draft.schedulePreset)}</b></div><div class="info-line"><span>Time</span><b>${escape(draft.scheduleTime)} · ${escape(draft.timeZoneId)}</b></div><div class="info-line"><span>Agent</span><b>${safe(itemName('agents',draft.agentId)||'No agent',55)}</b></div>`;
 const content=createKind==='agent'?[stepPurpose,stepKnowledge,stepTools,stepPermissions,stepReview][wizardStep]():createKind==='app'?[appDesign,appLayout,stepPermissions,stepReview][wizardStep]():[automationTask,automationSchedule,automationExecution,stepReview][wizardStep]();
 return pageHeading(title,'Different guided steps for agents, interactive apps and scheduled tasks.',`<span class="pill">${escape(orgName())}</span>`)+`<div class="row"><span class="muted small">What would you like to build?</span>${[['agent','Agent'],['app','App'],['automation','Automation']].map(([id,n])=>`<button class="chip ${createKind===id?'selected':''}" data-kind="${id}">${n}</button>`).join('')}</div><div class="steps">${steps.map((n,i)=>`<button class="step ${i===wizardStep?'current':i<wizardStep?'done':''}" data-step="${i}">${i+1} · ${n}</button>`).join('')}</div><div class="builder-layout"><section class="card"><div class="section-top"><h2>${wizardStep+1}. ${steps[wizardStep]}</h2><span class="pill">Step ${wizardStep+1} of ${steps.length}</span></div>${content}<div class="sticky-actions">${button('← Back','prevStep')}${button(wizardStep===steps.length-1?'✓ Create '+createKind:'Continue →',wizardStep===steps.length-1?'finishCreate':'nextStep','primary')}</div></section><aside class="card preview"><div class="row"><span class="iconbox">✧</span><div><h3>Live preview</h3><span class="tiny muted">Updates as you configure the tool</span></div></div><hr><h2>${safe(draft.name||'Your new '+createKind,90)}</h2><p>${safe(draft.description||'Describe what this resource will do.',300)}</p><div class="info-line"><span>Type</span><b>${escape(createKind)}</b></div>${summary}<div class="info-line"><span>Visibility</span><b>${escape(draft.visibility)}</b></div><hr><p class="tiny muted">These are saved demonstration records only. Apps are not deployed, tasks will not run at their scheduled time, and agents do not call a live AI model.</p></aside></div>`;
}
function stepPurpose(){return `<div class="fields">${field('Agent name *','draftName',draft.name,'text',false,'A clear, descriptive name')}${selectField('AI model','draftModel',modelOpts(),draft.model)}${field('What should this agent help with? *','draftDescription',draft.description,'textarea',true)}${field('System instructions','draftPrompt',draft.prompt,'textarea',true,'How should the agent behave?')}</div>`}
function stepKnowledge(){return `<p class="sub">Choose the document collections that this agent could consult.</p><div class="option-list" style="margin-top:19px">${all('knowledgeBases').map(x=>`<label class="option"><input type="checkbox" data-draftarray="knowledgeBaseIds" value="${escape(x.id)}" ${draft.knowledgeBaseIds.includes(x.id)?'checked':''}><span><b>${safe(x.name,100)}</b><br><small class="muted">${Number(x.documentCount||0)} documents · ${safe(x.sourceType||'Documents',40)}</small></span></label>`).join('')||'<div class="empty">No knowledge bases available.</div>'}</div>`}
function stepTools(){return `<p class="sub">Combine reusable skills and connections with your agent (demonstration only).</p>${[['agentSkills','skillIds','Skills'],['mcpServers','mcpServerIds','External connections (MCP)'],['apps','appIds','Apps']].map(([type,key,title])=>`<h3 style="margin:20px 0 12px">${title}</h3><div class="option-list">${all(type).map(x=>`<label class="option"><input type="checkbox" data-draftarray="${key}" value="${escape(x.id)}" ${draft[key].includes(x.id)?'checked':''}><span><b>${safe(x.name,95)}</b><br><small class="muted">${safe(x.description,100)}</small></span></label>`).join('')||'<div class="empty">No resources available</div>'}</div>`).join('')}<h3 style="margin:20px 0 10px">Built-in capabilities</h3><div class="option-list">${baseArr('plugins').filter(x=>x.enabled).map(x=>`<label class="option"><input type="checkbox" data-draftarray="pluginIds" value="${escape(x.id)}" ${draft.pluginIds.includes(x.id)?'checked':''}><span><b>${safe(x.name,75)}</b><br><small class="muted">${safe(x.description,100)}</small></span></label>`).join('')}</div>`}
function stepPermissions(){return `<p class="sub">Choose who can find and use this ${escape(createKind)}. Permissions are simulated in the frontend.</p><div class="share-choice" style="margin:19px 0">${[['private','Private','Only your personal demo workspace'],['team','Team','People in selected groups'],['organization','Organization','Everyone in the selected demo organization']].map(([id,n,d])=>`<label><input type="radio" name="draftVisibility" value="${id}" ${draft.visibility===id?'checked':''}> ${n}<small>${d}</small></label>`).join('')}</div><h3>Teams allowed to use it</h3><div class="option-list" style="margin-top:12px">${all('groups').map(g=>`<label class="option"><input type="checkbox" data-draftarray="teamIds" value="${escape(g.id)}" ${draft.teamIds.includes(g.id)?'checked':''}><span>${safe(g.name,60)} <span class="muted tiny">(${g.memberCount} members)</span></span></label>`).join('')}</div>`}
function appDesign(){return `<div class="fields">${field('App name *','draftName',draft.name)}${selectField('App layout','draftAppFormat',[{value:'form',name:'Form / guided input'},{value:'dashboard',name:'Dashboard / results'},{value:'assistant',name:'Interactive assistant panel'},{value:'calculator',name:'Calculator'}],draft.appFormat,'Choose how the user interacts with the app')}${field('What will the app do? *','draftDescription',draft.description,'textarea',true)}${field('Instructions for the app','draftPrompt',draft.prompt,'textarea',true,'Optional description of its behavior')}</div>`}
function appLayout(){return `<p class="sub">Design the information users provide and the result they expect. This is a UI prototype, not an executable app.</p><div class="fields" style="margin-top:15px">${field('User input fields','draftAppInputs',draft.appInputs,'textarea',true,'Example: Customer question, Order number')}${field('Expected result / output','draftAppOutput',draft.appOutput,'textarea',true,'Example: Summary and next steps')}</div><div class="notice">An App is an interactive interface. Unlike an Agent, it needs inputs, outputs and a layout—not an AI model, knowledge bases and agent tools by default.</div>`}
function automationTask(){return `<div class="fields">${field('Automation name *','draftName',draft.name)}${field('What is the task for? *','draftDescription',draft.description,'textarea',true)}${field('Instruction to run','draftPrompt',draft.prompt,'textarea',true,'Example: Prepare a short summary of pending deliveries')}</div>`}
function automationSchedule(){return `<p class="sub">Set when the task would run in a connected production system.</p><div class="fields" style="margin-top:15px">${selectField('Repeat','draftSchedule',[{value:'daily',name:'Every day'},{value:'weekdays',name:'Monday–Friday'},{value:'weekly',name:'Every Monday'},{value:'monthly',name:'First day of each month'}],draft.schedulePreset)}${field('Time (24-hour)','draftScheduleTime',draft.scheduleTime,'time')}${selectField('Time zone','draftTimeZone',[{value:'Europe/Rome',name:'Europe/Rome'},{value:'Europe/Lisbon',name:'Europe/Lisbon'},{value:'UTC',name:'UTC'}],draft.timeZoneId)}</div><div class="notice">The task will be saved as disabled. This demonstration does not schedule background execution.</div>`}
function automationExecution(){const opts=[{value:'',name:'No agent selected'},...all('agents').map(a=>({value:a.id,name:a.name}))];return `<p class="sub">Choose an existing agent that would perform the task. This links the task to a reusable organization agent.</p><div class="fields" style="margin-top:15px">${selectField('Agent to run','draftAgentId',opts,draft.agentId)}${field('Task prompt','draftPrompt',draft.prompt,'textarea',true,'What should the agent do at the scheduled time?')}</div><div class="notice">Selecting an agent does not execute it. The connection is stored as a demonstration.</div>`}
function stepReview(){let details=createKind==='agent'?`<div class="info-line"><span>Model</span><b>${safe(db.models.find(x=>x.id===draft.model)?.name||draft.model)}</b></div><div class="info-line"><span>Knowledge bases</span><b>${draft.knowledgeBaseIds.length}</b></div><div class="info-line"><span>Connected tools</span><b>${draft.skillIds.length+draft.mcpServerIds.length+draft.appIds.length}</b></div>`:createKind==='app'?`<div class="info-line"><span>Layout</span><b>${escape(draft.appFormat)}</b></div><div class="info-line"><span>Inputs</span><b>${safe(draft.appInputs,90)}</b></div><div class="info-line"><span>Output</span><b>${safe(draft.appOutput,90)}</b></div>`:`<div class="info-line"><span>Schedule</span><b>${escape(draft.schedulePreset)} at ${escape(draft.scheduleTime)}</b></div><div class="info-line"><span>Time zone</span><b>${escape(draft.timeZoneId)}</b></div><div class="info-line"><span>Linked agent</span><b>${draft.agentId?safe(itemName('agents',draft.agentId),90):'None'}</b></div><div class="info-line"><span>Execution</span><b>Disabled — demo only</b></div>`;return `<div class="utility-block"><h3>${safe(draft.name||'Untitled tool',120)}</h3><p class="sub">${safe(draft.description||'No purpose described',300)}</p></div><div class="info-line"><span>Resource type</span><b>${escape(createKind)}</b></div>${details}<div class="info-line"><span>Visibility</span><b>${escape(draft.visibility)}</b></div><div class="notice">Creates a browser-local demonstration record. It does not provision a remote agent, publish a functioning app or run a scheduled task.</div>`}
function cronFromSchedule(){const [hh,mm]=(draft.scheduleTime||'09:00').split(':').map(Number);const h=Number.isInteger(hh)&&hh>=0&&hh<24?hh:9,m=Number.isInteger(mm)&&mm>=0&&mm<60?mm:0;const suffix={daily:'* * *',weekdays:'* * 1-5',weekly:'* * 1',monthly:'1 * *'}[draft.schedulePreset]||'* * *';return `${m} ${h} ${suffix}`}
function create(){
 if(!draft.name.trim()||!draft.description.trim()){status='Add a name and purpose before creating the tool.';wizardStep=0;render();return}
 const now=new Date().toISOString();const type=createKind==='agent'?'agents':createKind==='app'?'apps':'scheduledTasks';const id='demo-'+type+'-'+Date.now().toString(36);
 const o={id,name:draft.name.trim(),description:draft.description.trim(),organizationId:org,origin:'createdInPrototype',isPublic:draft.visibility==='organization',ownerGroupId:draft.teamIds[0]||null,createdAt:now};
 if(type==='agents')Object.assign(o,{defaultModelId:draft.model,isModelChangeable:true,systemPrompt:draft.prompt,knowledgeBaseIds:[...draft.knowledgeBaseIds],skillIds:[...draft.skillIds],pluginIds:[...draft.pluginIds],mcpServerIds:[...draft.mcpServerIds],appIds:[...draft.appIds]});
 if(type==='apps')Object.assign(o,{public:draft.visibility==='organization',status:'Prototype',isListedInLibrary:draft.visibility!=='private',usageDescription:draft.description,appFormat:draft.appFormat,inputsDescription:draft.appInputs,outputDescription:draft.appOutput,systemPrompt:draft.prompt,knowledgeBaseIds:[]});
 if(type==='scheduledTasks')Object.assign(o,{isEnabled:false,cronExpression:cronFromSchedule(),schedulePreset:draft.schedulePreset,scheduleTime:draft.scheduleTime,timeZoneId:draft.timeZoneId,prompt:draft.prompt||draft.description,agentId:draft.agentId||null,knowledgeBaseIds:[]});
 addRecord(type,o);setState(id,{visibility:draft.visibility,teamIds:draft.teamIds});if(type==='agents'&&selectedProject()){setProjectAgents(local.project,[...projectAgentIds(local.project),id]);discoverScope='project'}
 picked=id;sourcePicked=id;filter='All';query='';if(type!=='agents')discoverScope='organization';status=`Created ${o.name} in this browser${type==='agents'&&selectedProject()?' and linked it to '+selectedProject().name:''}. ${type==='scheduledTasks'?'Automation is disabled: it will not execute.':'You can now inspect it.'}`;page='discover';render();
}
function listing(type){const title={projects:'Projects',knowledgeBases:'Knowledge bases',scheduledTasks:'Scheduled tasks'}[type];const items=all(type);return pageHeading(title,`Explore ${title.toLowerCase()} for ${escape(orgName())}.`,button('＋ Create '+(type==='scheduledTasks'?'automation':type==='projects'?'project':'knowledge base'),'listCreate','primary'))+`<div class="row" style="margin-bottom:16px"><span class="pill">${items.length} records</span><span class="muted tiny">Source records and changes saved in this browser</span></div>${type==='projects'?'<div class="notice">Projects are workspaces. Agents in the organization library are reusable, but are not automatically linked to every project. Open a project to choose its agents.</div>':''}<div class="tool-grid">${items.map(x=>type==='projects'?`<button class="tool-card" data-project="${escape(x.id)}"><div class="row between"><span class="iconbox">▣</span><span class="pill">Project</span></div><h3>${safe(x.name,80)}</h3><p>${safe(x.description,165)}</p><div class="metadata">${projectAgentIds(x.id).length} linked agents · ${(x.knowledgeBaseIds||[]).length} knowledge bases</div><div class="project-card-action">Open project →</div></button>`:toolCard({...x,type})).join('')||'<div class="empty">Nothing yet. Create a resource to get started.</div>'}</div>`}
function projectDetails(){const p=record('projects',selectedProjectId);if(!p)return pageHeading('Project','Select a project from Projects.')+button('← Back to Projects','projects');const linked=projectAgents(p.id);const available=all('agents').filter(a=>!projectAgentIds(p.id).includes(a.id));return `<div class="detail-top"><button class="btn" data-page="projects">← Back to Projects</button><span class="pill">${escape(orgName())}</span></div>`+pageHeading(safe(p.name,110),'Manage the agents that are explicitly linked to this project.')+`<div class="two-col"><section class="card"><h2>Agents linked to this project <span class="pill">${linked.length}</span></h2><p class="sub">Only these agents will appear in the Agent selector when this project is selected.</p>${linked.length?linked.map(a=>`<div class="info-line"><div><b>${safe(a.name,90)}</b><div class="muted tiny">${safe(a.description,140)}</div></div><button class="btn" data-unlinkagent="${escape(a.id)}">Remove</button></div>`).join(''):'<div class="empty">No agents linked yet. Add one from the organization library below.</div>'}<hr><h3>Add an existing organization agent</h3><p class="sub">Adding an agent to this project does not remove it from the organization library or other projects.</p>${available.length?`<div class="row project-add-row"><select id="projectAgentToAdd" aria-label="Organization agent to link">${available.map(a=>`<option value="${escape(a.id)}">${safe(a.name,95)}</option>`).join('')}</select>${button('＋ Add to project','linkProjectAgent','primary')}</div>`:'<p class="sub">All available agents are already linked.</p>'}</section><aside class="card"><h2>Project context</h2><p class="sub">${safe(p.description,420)}</p><div class="info-line"><span>Knowledge bases in project</span><b>${(p.knowledgeBaseIds||[]).length}</b></div>${(p.knowledgeBaseIds||[]).map(id=>`<div class="info-line"><span>${safe(itemName('knowledgeBases',id),90)}</span><span class="pill">Knowledge</span></div>`).join('')}<hr><p class="sub">Agents are shared tools. Linking one here only establishes project membership in this prototype.</p><button class="btn primary" data-action="useProject">✓ Use this project</button></aside></div>`}
let selectedProjectId='';

function connections(){let x=findAny(sourcePicked)||all('agents')[0]&&{...all('agents')[0],type:'agents'};if(!x)return pageHeading('How this solution works','View how tools and information connect.')+'<div class="empty">No agents or tools yet.</div>';sourcePicked=x.id;let links=connectionsFor(x).slice(0,7);const placements=[[0,0],[0,1],[0,2],[1,0],[1,2],[2,0],[2,2]];return pageHeading('How this solution works','Understand what is connected and where answers come from.',button('＋ Add connection','addConnection','primary'))+`<div class="row" style="margin-bottom:18px"><label class="field">Explore component ${selector(gather().map(z=>({value:z.id,name:z.name})),sourcePicked,'id="connectionSource"')}</label><span class="tag">Links shown are read from sample data or your local creations</span></div><div class="two-col"><div class="network-box"><svg viewBox="0 0 900 470" preserveAspectRatio="none" class="network-svg"><g stroke="#a47be9" stroke-width="2" fill="none">${links.map((z,i)=>{const [row,col]=placements[i];const x1=[155,450,745][col],y1=[70,235,405][row];return `<path d="M ${x1} ${y1} Q ${450} ${y1} 450 235"/>`}).join('')}</g></svg><div class="nodes"><button class="node main-node" data-node="${escape(x.id)}"><strong>✧ ${safe(x.name,70)}</strong><small>${typeMap[x.type]}</small></button>${links.map((z,i)=>{const [row,col]=placements[i];return `<button class="node" data-node="${escape(z.id)}" style="grid-row:${row+1};grid-column:${col+1}"><strong>${safe(z.name,65)}</strong><small>${escape(typeMap[z.type]||'Plugin')}</small></button>`}).join('')}</div></div><div class="card inspector"><h2>Connection details</h2><p class="sub">Selected resource</p><div class="notice"><b>${safe(x.name,100)}</b> · ${typeMap[x.type]}</div><p class="sub">${safe(x.description||x.prompt||'',300)}</p><hr><h3>Connected building blocks</h3>${links.map(z=>`<div class="info-line"><span>${safe(z.name,65)}</span><small class="muted">${typeMap[z.type]||'Plugin'}</small></div>`).join('')||'<p class="sub">No linked components. Add a connection to demonstrate composition.</p>'}<div style="margin-top:20px" class="row">${button('Manage access','share')}${button('Open KON Board ↗','board')}</div></div></div><p class="footnote">Connections are descriptive data relationships, not live execution traces. Newly linked resources are saved only in your browser.</p>`}
function share(){let x=findAny(sourcePicked)||findAny(picked)||all('agents')[0]&&{...all('agents')[0],type:'agents'};if(!x)return pageHeading('Share and manage access','Choose who can use each tool.')+'<div class="empty">No tools available.</div>';sourcePicked=x.id;const st=activeState(x.id);const v=visibility(x);const teamIds=st.teamIds||[];return pageHeading('Share and manage access','Decide who can use this tool and where it appears.',button('✓ Save sharing settings','saveSharing','primary'))+`<div class="card" style="margin-bottom:15px"><div class="section-top"><div class="row"><span class="iconbox">${icon(x.type)}</span><div><h2>${safe(x.name,100)}</h2><p class="sub">${typeMap[x.type]} · ${safe(orgName())}</p></div></div><label class="field">Selected tool ${selector(gather().map(z=>({value:z.id,name:z.name})),x.id,'id="shareSource"')}</label></div><p class="muted small">${safe(x.description||x.prompt||'',210)}</p></div><div class="two-col"><section class="card"><h2>Visibility</h2><p class="sub">Choose who can see this tool.</p><div class="share-choice" style="margin:18px 0">${[['private','Private','Only you'],['team','Team','Selected groups'],['organization','Organization','Everyone in the organization']].map(([k,n,d])=>`<label><input name="shareVis" type="radio" value="${k}" ${v===k?'checked':''}> ${n}<small>${d}</small></label>`).join('')}</div><h3 style="margin:20px 0 12px">Teams and users</h3><div class="table-wrap"><table><thead><tr><th>Group</th><th>Members</th><th>Can use</th></tr></thead><tbody>${all('groups').map(g=>`<tr><td>${safe(g.name,80)}</td><td>${g.memberCount}</td><td><input class="toggle" data-shareteam="${escape(g.id)}" type="checkbox" ${teamIds.includes(g.id)?'checked':''}></td></tr>`).join('')}</tbody></table></div></section><aside class="card"><h2>Published to</h2><p class="sub">Choose where this resource appears.</p>${[['library','Team Library','Discoverable in the shared library'],['project','Project','Available in the selected project'],['shared','Shared tools','Reusable by other teams']].map(([id,n,d])=>`<label class="info-line"><span><b>${n}</b><br><span class="muted tiny">${d}</span></span><input class="toggle" data-sharetoggle="${id}" type="checkbox" ${st['publish_'+id]===true?'checked':''}></label>`).join('')}<hr><h3>Access summary</h3><p class="sub">This frontend demonstrates permissions but does not enforce them on a server.</p><div class="notice">The selected visibility and team access will be saved locally for this browser.</div>${button('View connections','connections')}</aside></div>`}
function chat(){const example=baseArr('chats').find(c=>c.id===selectedChat),agent=record('agents',local.agent),proj=selectedProject();const datasetFiles=(example?.knowledgeFiles||[]).map(x=>typeof x==='string'?x:(x.fileName||x.name||'Sample document'));
return `<div class="chat-screen"><div class="section-top"><div><h2>${example?safe(example.title,110):'New chat'}</h2><p class="sub">${example?'Conversation record from the hackathon dataset':'Choose a model, project and agent above, or start a conversation with a document.'}</p></div>${button('Discover agents','discover')}</div><div class="chat-layout"><div><div class="conversation-area">${example?`<div class="chat-bubble"><b>Sample user message</b><p>${safe(example.messages?.find(m=>m.role==='user')?.content||example.title,1500)}</p></div><p class="tiny muted">Dataset example: no AI reply is generated here.</p>`:''}${simChat.map(c=>`<div class="chat-bubble ${c.role==='assistant'?'ai':''}"><b>${c.role==='assistant'?'KON Dash demo':'You'}</b><p>${safe(c.text,1500)}</p>${c.files?.length?`<div class="chat-file-line">${c.files.map(f=>`<span class="tag">▤ ${safe(f.name,70)}</span>`).join('')}</div>`:''}</div>`).join('')||(!example?'<div class="chat-welcome"><h1>What would you like to know?</h1><p class="sub">Attach a document or ask a question.</p></div>':'')}</div>${composer()}</div><aside class="card chat-source-panel"><div class="section-top"><h3>Sources & tools</h3></div><div class="source-group"><b>Model</b><p>${safe(local.model||example?.selectedModelId||'general',60)}</p></div><div class="source-group"><b>Project</b><p>${proj?safe(proj.name,85):'No project'}</p></div><div class="source-group"><b>Agent</b><p>${agent?safe(agent.name,85):example?.selectedAgentId?safe(itemName('agents',example.selectedAgentId),85):'No agent selected'}</p></div><div class="source-group"><b>Reusable knowledge</b>${agent&&(agent.knowledgeBaseIds||[]).length?(agent.knowledgeBaseIds||[]).map(id=>`<p>▤ ${safe(itemName('knowledgeBases',id),85)}</p>`).join(''):proj&&(proj.knowledgeBaseIds||[]).length?(proj.knowledgeBaseIds||[]).map(id=>`<p>▤ ${safe(itemName('knowledgeBases',id),85)}</p>`).join(''):'<p>None linked</p>'}</div><div class="source-group"><b>Chat attachments</b>${simChat.filter(c=>c.role==='user').flatMap(c=>c.files||[]).length?attachmentTrace(simChat.filter(c=>c.role==='user').flatMap(c=>c.files||[])):''}${attachmentTrace(chatAttachments)}${datasetFiles.map(n=>`<div class="attachment-source"><b>▤ ${safe(n,90)}</b><small>Dataset example attachment</small></div>`).join('')}</div></aside></div></div>`}

function managePage(){
 const sections=[['knowledge','Knowledge bases','Browse reusable company information and the documents linked to agents.','▤'],['automations','Scheduled tasks','Review saved automations and launch demo previews.','◷'],['connections','Connections','Explore how agents, applications and knowledge are connected.','⇄'],['share','Access & sharing','Choose who may use an individual tool.','♧'],['extensions','Extensions','Browse Skills and MCP integrations.','⚒'],['memory','Memory','Inspect the sample workspace context.','◉'],['settings','Settings','Advanced model and organization options.','⚙']];
 return pageHeading('Manage','Advanced tools and settings are here when you need them. To change a specific tool, open it from Discover.')+`<div class="manage-grid">${sections.map(([p,n,d,i])=>`<button class="manage-tile" data-page="${p}"><span class="iconbox">${i}</span><span><b>${n}</b><small>${d}</small></span><span class="manage-arrow">→</span></button>`).join('')}</div><div class="notice" style="margin-top:20px">Workspace settings are stored in this browser. External services are not connected.</div>`;
}
function extensionPage(){const skill=all('agentSkills'),mcp=all('mcpServers');return pageHeading('Extensions','Skills and MCP servers bring extra capabilities to KON Dash.',button('Create a tool with these capabilities','create','primary'))+`<div class="two-col"><section class="card"><h2>Skills</h2><p class="sub">Reusable instructions for Word, PDF, research, analysis and other tasks.</p><div class="extension-list">${skill.slice(0,22).map(x=>`<div class="extension-row"><span class="iconbox">⚒</span><div><b>${safe(x.name,75)}</b><p class="sub">${safe(x.description,145)}</p></div><span class="pill">${x.origin==='preinstalledByKonDash'?'Built in':'Custom'}</span></div>`).join('')||'<div class="empty">No skills available.</div>'}</div></section><section class="card"><h2>MCP Servers</h2><p class="sub">Connections to approved external business systems.</p><div class="extension-list">${mcp.map(x=>`<div class="extension-row"><span class="iconbox">⇄</span><div><b>${safe(x.name,75)}</b><p class="sub">${safe(x.description,145)}</p></div><span class="pill">${x.enabled===false?'Off':'Configured'}</span></div>`).join('')||'<div class="empty">No MCP servers configured for this organization.</div>'}</div><div class="notice">This demo only displays sample connections. It never contacts external MCP servers.</div></section></div>`}
function memoryPage(){const memories=baseArr('memories');return pageHeading('Memory','Review saved personal and project context from the sample workspace.')+`<div class="card"><div class="section-top"><h2>Stored memories</h2><span class="pill">${memories.length} examples</span></div>${memories.map(x=>`<div class="extension-row"><span class="iconbox">◉</span><div><b>${safe(x.title||x.name||x.scope||'Memory',90)}</b><p class="sub">${safe(x.content||x.text||x.value||x.description||'',210)}</p></div></div>`).join('')||'<div class="empty">No memories recorded for this organization.</div>'}<div class="notice">These are illustrative records from the hackathon dataset, not personal data.</div></div>`}
function settingsPage(){return pageHeading('Settings','Advanced administration is kept separate from everyday use.')+`<div class="tool-grid">${[['Models','Manage available AI models and defaults.','Model selection is illustrated in the top bar.'],['Organization access','Configure groups and tool visibility.','Use Share & manage to preview permissions.'],['Extensions','Configure Skills and MCP connections.','Browse real fictional example extensions.'],['Usage & costs','Monitor how your organization uses AI.','Open KON Board for the detailed analytics.']].map(([name,desc,note],i)=>`<div class="card"><span class="iconbox">${['◉','♧','⚒','▥'][i]}</span><h2 style="margin-top:14px">${name}</h2><p class="sub">${desc}</p><p class="tiny muted" style="margin-top:12px">${note}</p></div>`).join('')}</div><div class="notice">Azure configuration, login, API keys and service permissions are not simulated as real administrative operations.</div>`}
function showNotice(){if(!status)return;const el=document.createElement('div');el.className='notice '+(status.startsWith('Created')||status.startsWith('Saved')?'success':'warning');el.setAttribute('role','status');el.textContent=status;$('main').prepend(el);status=''}
function syncDraft(){const pairs=[['draftName','name'],['draftDescription','description'],['draftPrompt','prompt'],['draftModel','model'],['draftCron','cronExpression'],['draftAppFormat','appFormat'],['draftAppInputs','appInputs'],['draftAppOutput','appOutput'],['draftSchedule','schedulePreset'],['draftScheduleTime','scheduleTime'],['draftTimeZone','timeZoneId'],['draftAgentId','agentId']];for(const[id,key]of pairs)if($(id))draft[key]=$(id).value}
function formPrompt(){const val=$('chatPrompt')?.value?.trim();if(!val&&!chatAttachments.length)return;simChat.push({role:'user',text:val||'Attached documents for review.',files:chatAttachments.map(f=>({...f}))},{role:'assistant',text:'Demo reply only. Files are shown in the Sources & tools panel, but no AI analysis, document retrieval or model invocation was performed.'});chatAttachments=[];local.draftPrompt='';open('chat')}
function createQuick(type){if(type==='projects'){const name=prompt('Project name (demo):');if(!name?.trim())return;const desc=prompt('Short project description:')||'';addRecord('projects',{id:'demo-prj-'+Date.now(),name:name.trim(),description:desc,organizationId:org,knowledgeBaseIds:[],created:new Date().toISOString()});status='Created a project in this browser.';render();return}if(type==='knowledgeBases'){const name=prompt('Knowledge base name (demo):');if(!name?.trim())return;addRecord('knowledgeBases',{id:'demo-kb-'+Date.now(),name:name.trim(),description:prompt('Short description:')||'',organizationId:org,documentCount:0,sourceType:'Manual demo',usedBy:{agentIds:[]}});status='Created a knowledge base in this browser.';render();return}startCreate('automation')}
function linkDialog(){const src=findAny(sourcePicked)||all('agents')[0];if(!src){status='Choose a tool first';render();return}const kbs=all('knowledgeBases').filter(k=>!(src.knowledgeBaseIds||[]).includes(k.id));if(!kbs.length){status='Every available knowledge base is already connected, or none exists.';render();return}const names=kbs.map((k,i)=>`${i+1}: ${k.name}`).join('\n');const v=prompt(`Select a knowledge base to link to ${src.name} by number:\n${names}`);const n=Number(v);if(!Number.isInteger(n)||n<1||n>kbs.length)return;const ids=[...(src.knowledgeBaseIds||[]),kbs[n-1].id];updateRecord(src.type,src.id,{knowledgeBaseIds:ids});status=`Linked ${kbs[n-1].name} to ${src.name} (demo only).`;render()}
function applySharing(){const src=findAny(sourcePicked);if(!src)return;const vis=document.querySelector('input[name="shareVis"]:checked')?.value||visibility(src);const teams=[...document.querySelectorAll('[data-shareteam]:checked')].map(n=>n.dataset.shareteam);const out={visibility:vis,teamIds:teams};for(const el of document.querySelectorAll('[data-sharetoggle]'))out['publish_'+el.dataset.sharetoggle]=el.checked;setState(src.id,out);status='Saved sharing settings in this browser.';render()}
const orgGuard=new Set(['orgSelect','topModel','topProject','topAgent']);
document.addEventListener('input',e=>{if(e.target.id==='searchBox'){query=e.target.value;const a=e.target.selectionStart;render();if($('searchBox')){$('searchBox').setSelectionRange(a,a)}return}if(e.target.id==='chatPrompt'){local.draftPrompt=e.target.value;return}if(e.target.id==='demoQuestion'){local.demoQuestionDraft=e.target.value;return}if(e.target.id?.startsWith('draft')){syncDraft();const panel=document.querySelector('.preview');if(panel){const s=window.scrollY;const pos=e.target.selectionStart;render();const back=$(e.target.id);if(back){back.focus();try{back.setSelectionRange(pos,pos)}catch{}}window.scrollTo(0,s)}}});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='orgSelect'){chatAttachments=[];agentAttachments=[];org=el.value;local.project='';local.agent='';saveLocal();filter='All';discoverScope='project';query='';picked='';sourcePicked='';draft=defaultDraft();status='';open('home');return}if(el.id==='topModel'){local.model=el.value;saveLocal();return}if(el.id==='topProject'){local.project=el.value;local.agent='';discoverScope='project';picked='';saveLocal();render();return}if(el.id==='topAgent'){local.agent=el.value;saveLocal();return}if(['draftAppFormat','draftSchedule','draftScheduleTime','draftTimeZone','draftAgentId'].includes(el.id)){syncDraft();render();return}if(el.id==='connectionSource'||el.id==='shareSource'){sourcePicked=el.value;render();return}if(el.matches('[data-draftarray]')){let key=el.dataset.draftarray;draft[key]??=[];draft[key]=el.checked?[...new Set([...draft[key],el.value])]:draft[key].filter(x=>x!==el.value);render();return}if(el.name==='draftVisibility'){draft.visibility=el.value;render();return}if(el.matches('[data-shareteam],[data-sharetoggle]')){dirty=true;return}});
document.addEventListener('change',e=>{if(e.target.id==='chatAttachInput'||e.target.id==='agentAttachInput'){receiveFiles(e.target.files,e.target.id==='agentAttachInput'?'agent':'chat')}});
document.addEventListener('click',e=>{const btn=e.target.closest('button,[data-item]');if(!btn)return;if(btn.dataset.page){if(btn.dataset.page==='chat'){selectedChat='';simChat=[]}open(btn.dataset.page);return}if(btn.dataset.chat){selectedChat=btn.dataset.chat;simChat=[];chatAttachments=[];open('chat');return}if(btn.dataset.removeFile){const [kind,idx]=btn.dataset.removeFile.split(':');const a=kind==='agent'?agentAttachments:chatAttachments;a.splice(Number(idx),1);render();return}if(btn.dataset.openApp){previewId=btn.dataset.openApp;appResult=null;open('appPreview');return}if(btn.dataset.project){selectedProjectId=btn.dataset.project;open('projectDetails');return}if(btn.dataset.unlinkagent){const ids=projectAgentIds(selectedProjectId).filter(id=>id!==btn.dataset.unlinkagent);setProjectAgents(selectedProjectId,ids);if(local.project===selectedProjectId&&local.agent===btn.dataset.unlinkagent){local.agent='';saveLocal()}status='Removed agent from this project. It remains in the organization library.';render();showNotice();return}if(btn.dataset.detailTab){detailTab=btn.dataset.detailTab;render();return}if(btn.dataset.discoverScope){discoverScope=btn.dataset.discoverScope;picked='';render();return}if(btn.dataset.filter){filter=btn.dataset.filter;picked='';render();return}if(btn.dataset.select){picked=btn.dataset.select;sourcePicked=picked;detailTab='overview';const item=findAny(picked);if(item?.type==='projects'){selectedProjectId=picked;open('projectDetails')}else open('toolDetails');return}if(btn.dataset.item){const item=findAny(btn.dataset.item);if(item){sourcePicked=item.id;picked=item.id;detailTab='overview';if(item.type==='projects'){selectedProjectId=item.id;open('projectDetails')}else open('toolDetails')}return}if(btn.dataset.kind){syncDraft();startCreate(btn.dataset.kind);return}if(btn.dataset.step){syncDraft();wizardStep=Math.max(0,Math.min(currentSteps().length-1,Number(btn.dataset.step)));render();return}if(btn.dataset.node){const x=findAny(btn.dataset.node);if(x){sourcePicked=x.id;render()}return}const action=btn.dataset.action;if(!action)return;switch(action){case'projectDetails':if(selectedProject()){selectedProjectId=local.project;open('projectDetails')}else open('projects');return;case'linkExistingApp':{const a=findAny(picked);const appId=$('existingAppSelect')?.value;if(!a||a.type!=='agents'||!record('apps',appId))return;updateRecord('agents',a.id,{appIds:[...new Set([...(a.appIds||[]),appId])]});status='Connected an existing App to this agent. The App remains reusable.';render();showNotice();return}case'linkProjectAgent':{const id=$('projectAgentToAdd')?.value;if(!id||!record('agents',id))return;setProjectAgents(selectedProjectId,[...projectAgentIds(selectedProjectId),id]);status='Agent linked to this project. It remains reusable in the organization library.';render();showNotice();return}case'useProject':local.project=selectedProjectId;local.agent='';discoverScope='project';picked='';saveLocal();status='This project is now selected in the top bar.';open('projectDetails');showNotice();return;case'backTool':picked=previewId;sourcePicked=picked;detailTab='overview';demoRun=false;appResult=null;open('toolDetails');return;case'tryAgent':{const x=findAny(picked)||findAny(sourcePicked);if(!x||x.type!=='agents')return;previewId=x.id;demoPrompt='';demoReply='';agentAttachments=[];local.demoQuestionDraft='';open('agentTry');return}case'previewApp':{const x=findAny(picked)||findAny(sourcePicked);if(!x||x.type!=='apps')return;previewId=x.id;appResult=null;open('appPreview');return}case'previewAutomation':{const x=findAny(picked)||findAny(sourcePicked);if(!x||x.type!=='scheduledTasks')return;previewId=x.id;demoRun=false;open('automationPreview');return}case'fillDemoQuestion':local.demoQuestionDraft='How can I check the status of a customer shipment?';render();return;case'sendDemoQuestion':{const a=previewRecord('agents');const q=($('demoQuestion')?.value||'').trim();if(!a||!q)return;demoPrompt=q;demoReply=mockAgentReply(a,q);local.demoQuestionDraft='';render();return}case'calculateDemoApp':{const a=previewRecord('apps');if(!a)return;if(isShippingCalculator(a)){const distance=Number($('appDistance')?.value),weight=Number($('appWeight')?.value),transport=$('appTransport')?.value||'road';if(!Number.isFinite(distance)||distance<0||!Number.isFinite(weight)||weight<0||distance>100000||weight>100000){status='Enter a valid non-negative distance and weight.';showNotice();return}const rates={road:.45,express:.75,air:1.8};appResult={distance,weight,transport,total:Math.round((10+distance*(rates[transport]||.45)+weight*.12)*100)/100,calculated:true}}else appResult={customer:$('appCustomer')?.value||'',request:$('appRequest')?.value||'',calculated:true};render();return}case'resetDemoApp':appResult=null;render();return;case'previewDemoRun':demoRun=true;render();return;case'board':window.open('https://crissilva1901.github.io/kon-board-hackathon-2026/','_blank','noopener');return;case'discover':open('discover');return;case'connections':open('connections');return;case'share':open('share');return;case'create':startCreate('agent');return;case'sendChat':formPrompt();return;case'nextStep':syncDraft();if(wizardStep===0&&(!draft.name.trim()||!draft.description.trim())){status='Enter a name and a purpose to continue.';render();showNotice();return}wizardStep=Math.min(currentSteps().length-1,wizardStep+1);render();return;case'prevStep':syncDraft();wizardStep=Math.max(0,wizardStep-1);render();return;case'finishCreate':syncDraft();create();showNotice();return;case'addConnection':linkDialog();showNotice();return;case'saveSharing':applySharing();showNotice();return;case'listCreate':createQuick(page==='projects'?'projects':page==='knowledge'?'knowledgeBases':'scheduledTasks');showNotice();return}});
async function init(){try{const response=await fetch('./data.json');if(!response.ok)throw new Error('HTTP '+response.status);db=await response.json();readLocal();if(!db.kondash||!Array.isArray(db.organizations))throw Error('Invalid challenge dataset');if(!db.organizations.some(o=>o.id===org))org=db.organizations[0].id;if(local.project&&!record('projects',local.project)){local.project='';local.agent=''}if(local.project&&local.agent&&!projectAgentIds(local.project).includes(local.agent))local.agent='';render()}catch(err){console.error(err);$('app').innerHTML=`<div class="loading"><h2>Unable to load the sample data</h2><p class="sub">Open the published website or serve this folder from a local web server. Opening index.html directly with file:// may block JSON loading.</p><p class="small">${safe(err.message)}</p></div>`}}
init();
})();
